# Initialize an empty phonebook
phonebook = {}

def add_contact(name, phone_number):
    """Add a contact to the phonebook."""
    if name not in phonebook:
        phonebook[name] = (phone_number,)
    else:
        phonebook[name] += (phone_number,)
    print(f"Contact added: {name} {phone_number}")

def remove_contact(name):
    """Remove a contact from the phonebook."""
    if name in phonebook:
        del phonebook[name]
        print(f"Contact removed: {name}")
    else:
        print(f"Contact {name} not found.")

def view_contacts():
    """View all contacts in the phonebook."""
    print("\nPhonebook:")
    for name, phone_numbers in phonebook.items():
        print(f"{name}: {', '.join(phone_numbers)}")

def main():
    while True:
        command = input("\nEnter a command (add, remove, view, or quit): ").lower()

        if command == "add":
            name = input("Enter name: ")
            phone_number = input("Enter phone number: ")
            add_contact(name, phone_number)

        elif command == "remove":
            name = input("Enter name: ")
            remove_contact(name)

        elif command == "view":
            view_contacts()

        elif command == "quit":
            print("\nBye!")
            break

        else:
            print("Invalid command. Please try again.")

if __name__ == "__main__":
    main()
```

This program allows the user to add, remove, and view contacts in the phonebook. The `add_contact` function adds a contact with a single phone number, while the `remove_contact` function removes a contact from the phonebook. The `view_contacts` function prints all contacts in the phonebook. The `main` function handles user input and calls the appropriate functions based on the command.
